<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/budget.php';
if(!dev_is_super()){http_response_code(403);exit('Budget access denied.');}
$projectId=dev_active_project_id((int)($_GET['project_id']??0));$project=dev_require_project($projectId);dev_ensure_budget_schema();$budget=dev_budget_for_project($projectId,(int)($user['id']??0));
$query=db()->prepare('SELECT i.*,c.company_name,pc.trade_role FROM construction_budget_items i LEFT JOIN construction_project_companies pc ON pc.id=i.construction_project_company_id AND pc.construction_project_id=? LEFT JOIN construction_companies c ON c.id=pc.construction_company_id WHERE i.construction_project_budget_id=? ORDER BY i.display_order,i.id');$query->execute([$projectId,$budget['id']]);$items=$query->fetchAll()?:[];$equity=dev_budget_equity_sources((int)$budget['id']);$path=dev_build_budget_xlsx((string)$project['project_name'],$items,$budget,$equity);$filename=preg_replace('/[^A-Za-z0-9._-]+/','-',trim((string)$project['project_name'])).'-budget.xlsx';header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.$filename.'"');readfile($path);@unlink($path);exit;
